R.append(T(3066,"पोच्ड नाशपाती","सादी नाशपातियों को एक स्वादिष्ट मिठाई में बदलने के लिए तैयार हैं? वॉशिंगटन की DaVita रीनल आहार विशेषज्ञ गेरी अपनी किडनी-अनुकूल रेसिपी पोच्ड नाशपाती के साथ दिखाएँगी कि किडनी आहार के लिए स्वादिष्ट व्यंजन कैसे बनाएँ।","4","1/2 नाशपाती",
["1 छोटा चम्मच दालचीनी","2 छोटे चम्मच चीनी","2 अंजू नाशपाती","4 छोटे चम्मच मक्खन","2 कप क्रैनबेरी का रस"],
["एक छोटे कटोरे में दालचीनी और चीनी मिलाएँ।","नाशपाती को आधा काटें और चम्मच से बीज और डंठल निकाल दें।","नाशपाती के गोल हिस्से पर आड़ा पतला स्लाइस काट दें, ताकि वह बेकिंग डिश में सपाट टिक सके।","नाशपाती को छिलके वाली तरफ नीचे करके बेकिंग डिश में रखें और ऊपर से दालचीनी और चीनी का मिश्रण छिड़कें।","हर नाशपाती के बीज वाले गड्ढे में 1 छोटा चम्मच मक्खन रखें।","पैन के तले में रस डालें।","फॉइल से ढकें और 350° F पर लगभग 30 मिनट या जब तक काँटे से चुभाने पर नाशपाती नरम न लगे, बेक करें।"],
["यदि आपकी बेकिंग डिश उथली है, तो आपको कम रस की ज़रूरत पड़ सकती है। रस नाशपाती के किनारे की आधी ऊँचाई तक ही आना चाहिए।","चाहें तो परोसने से पहले नाशपाती के ऊपर रस डालें।","मधुमेह वाले लोग चीनी की जगह कम कैलोरी वाला क्रैनबेरी का रस और चीनी का विकल्प इस्तेमाल करें।"],["2 फल, कम पोटैशियम","1 वसा"]))
R.append(T(3067,"शतावरी फूलगोभी टॉर्टिला","विस्कॉन्सिन की DaVita रीनल आहार विशेषज्ञ सिंडी अपने मरीज़ों की किडनी आहार संबंधी व्यक्तिगत इच्छाओं पर ध्यान देती हैं और उन्हें हकीकत बनाने की कोशिश करती हैं। उनकी स्वादिष्ट और पेट भरने वाली शतावरी फूलगोभी टॉर्टिला जैसी स्वादिष्ट डायलिसिस आहार रेसिपी बनाने में सरल है और आपकी भूख मिटाएगी, आपके स्वाद को खुश रखेगी और सेहतमंद लैब रिपोर्ट के आपके सपनों को सच करने में मदद करेगी।","4","1/4 टॉर्टिला",
["2 कप शतावरी (एस्पैरागस), निवाले के आकार के टुकड़ों में कटी हुई","2 कप फूलगोभी, निवाले के आकार के टुकड़ों में कटी हुई","2 छोटे चम्मच ऑलिव ऑयल","1-1/2 कप प्याज़, बारीक कटा हुआ","लहसुन की 1 कली, बारीक कटी हुई","1 कप तरल कम कोलेस्ट्रॉल वाला अंडे का विकल्प","2 बड़े चम्मच ताज़ा अजमोद (पार्सले), बारीक कटा हुआ","1/4 छोटा चम्मच नमक","1/2 छोटा चम्मच ताज़ी पिसी काली मिर्च","1/4 छोटा चम्मच सूखी थाइम की पत्तियाँ, मसली हुई","1/4 छोटा चम्मच पिसा जायफल"],
["शतावरी और फूलगोभी के टुकड़ों को 1 बड़े चम्मच पानी के साथ माइक्रोवेव-सुरक्षित ढके हुए बर्तन में रखें। भाप से हल्का कुरकुरा नरम होने तक माइक्रोवेव में 3 से 5 मिनट पकाएँ।","प्याज़ को सुनहरा होने तक, लगभग 7 मिनट भूनें।","लहसुन डालें और चलाते हुए 1 मिनट और पकाएँ।","शतावरी, फूलगोभी, अंडे का विकल्प, अजमोद, नमक, काली मिर्च, थाइम और जायफल मिलाएँ।","आँच कम करें और ढककर तब तक पकाएँ जब तक जम न जाए और नीचे से भूरा न हो जाए, लगभग 10 से 15 मिनट।","चाकू से किनारों को ढीला करें और गरम थाली में पलट दें या सीधे स्किलेट से परोसें।"],
["स्पेन और दक्षिण अमेरिका में टॉर्टिला एक गोल, बिना मुड़ा हुआ ऑमलेट होता है जो आमतौर पर अंडों, सब्ज़ियों और मसालों से बनाया जाता है। इसके विपरीत, मैक्सिकन टॉर्टिला गेहूँ के आटे या पिसे मक्के से बनी पतली, चपटी रोटी होती है।"],["1 मांस","2 सब्ज़ी, मध्यम पोटैशियम"]))
R.append(T(3068,"रोज़मेरी के साथ भुनी हुई फूलगोभी","रोज़मेरी के साथ भुनी हुई फूलगोभी चखने के बाद फूलगोभी आसानी से आपकी पसंदीदा कम पोटैशियम वाली सब्ज़ी बन सकती है। DaVita की आहार विशेषज्ञ टीम द्वारा बनाई गई इस सब्ज़ी में तेल, थोड़े से नमक, काली मिर्च और ताज़ी रोज़मेरी का हल्का मसाला लगाया जाता है। रोज़मेरी के साथ भुनी हुई फूलगोभी बनाना आसान और किडनी-अनुकूल है।","9","2/3 कप",
["6 कप फूलगोभी के फूल (फ्लोरेट्स)","1 बड़ा चम्मच ताज़ी रोज़मेरी","1-1/2 बड़े चम्मच ऑलिव ऑयल","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["ओवन को 450° F पर पहले से गरम करें।","फूलगोभी के फूलों को निवाले के आकार के टुकड़ों में काटें। रोज़मेरी को काट लें।","एक बड़े कटोरे में फूलगोभी को बाकी सामग्री के साथ उछालकर मिलाएँ।","मसाला लगी फूलगोभी को बिना चिकनाई वाली बेकिंग शीट पर फैलाएँ।","15 मिनट भूनें; ओवन से निकालकर चलाएँ।","10 मिनट और भूनते रहें या जब तक फूलगोभी नरम और हल्की भूरी न हो जाए।"],
["फूलगोभी को चलाने के लिए बेकिंग शीट को ओवन से निकालते समय सावधानी बरतें।"],["1 सब्ज़ी, मध्यम पोटैशियम","1/2 वसा"]))
R.append(T(3069,"चिकन के साथ इटैलियन स्टाइल सब्ज़ियाँ और पास्ता","अपने अगले बड़े रात्रिभोज के लिए चिकन के साथ इटैलियन स्टाइल सब्ज़ियाँ और पास्ता की किडनी-अनुकूल रेसिपी आज़माएँ।","2","1-1/4 कप",
["1 बड़ा चम्मच ऑलिव ऑयल","1/2 कप हरी शिमला मिर्च","1/4 कप प्याज़","1/2 छोटा चम्मच लहसुन पाउडर","1/2 कप ताज़ी ब्रोकली के फूल","1 छोटा चम्मच सूखी रोज़मेरी","1 बड़ा चम्मच ताज़ी तुलसी","1/4 छोटा चम्मच लाल मिर्च के फ्लेक्स","1/8 छोटा चम्मच नमक","2 औंस पका हुआ चिकन","1/4 कप कम सोडियम वाला चिकन शोरबा","2 छोटे चम्मच कॉर्नस्टार्च","1 कप पास्ता ट्विस्ट, पका हुआ"],
["शिमला मिर्च और प्याज़ को काटें। चिकन को छोटे टुकड़ों में काटें।","एक बड़े नॉनस्टिक फ्राइंग पैन में तेल डालें और शिमला मिर्च, प्याज़ और ब्रोकली को तेज़ आँच पर चलाते हुए भूनें। रोज़मेरी, तुलसी, लाल मिर्च के फ्लेक्स, लहसुन पाउडर और नमक छिड़कें।","पका हुआ चिकन मिलाएँ।","चिकन शोरबे को कॉर्नस्टार्च के साथ मिलाएँ और सब्ज़ी और चिकन के मिश्रण में डालें। थोड़ा गाढ़ा होने तक पकाएँ। 1 कप गरम पका हुआ पास्ता मिलाएँ।","आँच से उतारें और परोसें।"],
["डायलिसिस वाले लोगों के लिए चिकन को बढ़ाकर 6 औंस किया जा सकता है। प्रति सर्विंग प्रोटीन की मात्रा बढ़कर 29 ग्राम हो जाएगी।","जल्दी तैयारी के लिए ताज़ी सब्ज़ियों की जगह इसी तरह की जमी हुई सब्ज़ियों का 1-1/4 कप मिश्रण इस्तेमाल करें।","तीखे भोजन के प्रति अपनी सहनशीलता के अनुसार लाल मिर्च के फ्लेक्स कम या ज़्यादा डालें।","खट्टा-चटपटा स्वाद देने के लिए नींबू का रस निचोड़ें या बाल्सेमिक सिरका छिड़कें।"],["1 मांस","1 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम","1 वसा"]))
R.append(T(3077,"कीमा बीफ़ और सब्ज़ी फॉइल पैक डिनर","जोड़ने में आसान और सफाई में आसान, DaVita की आहार विशेषज्ञ ग्रेस की रेसिपी, कीमा बीफ़ और सब्ज़ी फॉइल पैक डिनर, के लिए यह एकदम सही वर्णन है। साथ ही, आप प्रोटीन और सब्ज़ियों के प्रकार बदलकर इस रेसिपी को एक आसान, हमेशा काम आने वाला किडनी-अनुकूल रात का खाना बना सकते हैं।","1","3 औंस बीफ़, 3/4 कप सब्ज़ियाँ",
["4 औंस कीमा बीफ़","1/4 कप प्याज़","1 बड़ा चम्मच वूस्टरशायर सॉस","3/4 कप जमी हुई गाजर और मटर","1/4 छोटा चम्मच इटैलियन ड्रेसिंग का सूखा मिश्रण","1/4 छोटा चम्मच काली मिर्च"],
["ओवन को 375° F पर पहले से गरम करें। फॉइल के एक टुकड़े पर नॉनस्टिक कुकिंग स्प्रे करें। प्याज़ को काट लें।","कीमा बीफ़, प्याज़ और वूस्टरशायर सॉस को मिलाकर टिक्की बनाएँ और फॉइल पर रखें।","टिक्की के ऊपर जमी हुई मटर और गाजर रखें।","ऊपर से इटैलियन ड्रेसिंग का मिश्रण और काली मिर्च छिड़कें।","फॉइल को मोड़कर सील करें और बेकिंग शीट पर रखें। 35 मिनट बेक करें।","परोसने से पहले फॉइल पैकेट का एक सिरा सावधानी से खोलें और भाप को निकल जाने दें।"],
["फॉइल पर कुकिंग स्प्रे करें।","ओवन में रखने से पहले फॉइल पैकेट को बेकिंग शीट पर रखें।"],["3 मांस","1/2 स्टार्च","1-1/2 सब्ज़ी, मध्यम पोटैशियम"]))
R.append(T(3078,"हेज़लनट दालचीनी कॉफ़ी","किडनी-अनुकूल हेज़लनट दालचीनी कॉफ़ी की रेसिपी के साथ अपने दिन की स्वादिष्ट शुरुआत करें।","4","8 औंस (1 कप)",
["4 कप बनी हुई कॉफ़ी","8 छोटे चम्मच Torani® Sugar Free Classic Hazelnut Syrup","4 बड़े चम्मच 1% कम वसा वाला दूध","4 दालचीनी की डंडियाँ"],
["कॉफ़ी मेकर में कॉफ़ी बनाएँ। छोटे कपों में डालें।","हर मग में 2 छोटे चम्मच Torani® Sugar Free Classic Hazelnut Syrup और 1 बड़ा चम्मच दूध (या क्रीमर) डालें और हर एक को एक दालचीनी की डंडी से सजाएँ।"],
["Torani® Sugar Free सिरप के अलग-अलग फ्लेवर आज़माएँ।","यदि आप अपनी कॉफ़ी गहरी पसंद करते हैं, तो दूध न डालें।","कई नॉन-डेयरी क्रीमर में फॉस्फेट योजक होते हैं। यदि आप सिरप की जगह नॉन-डेयरी हेज़लनट क्रीमर इस्तेमाल करते हैं तो इसका ध्यान रखें।"],["कोई नहीं"]))
R.append(T(3079,"सिनमन रोल केक","सामग्री तैयारी उपयोगी सुझाव","24","2\" x 2\" का वर्ग",
["1-1/2 कप मक्खन","3-1/8 कप मैदा","1/4 छोटा चम्मच नमक","2 कप Splenda® बेकिंग ब्लेंड","1-1/2 छोटा चम्मच बेकिंग सोडा","3 छोटे चम्मच क्रीम ऑफ टार्टर","1-1/2 कप + 5 बड़े चम्मच राइस मिल्क (चावल का दूध), बिना फोर्टिफाइड","2 अंडे","3 छोटे चम्मच वनीला","1 कप Splenda® ब्राउन शुगर ब्लेंड","1 बड़ा चम्मच दालचीनी","1 कप पिसी चीनी"],
["ओवन को 350° F पर पहले से गरम करें।","1/2 कप मक्खन पिघलाएँ और बाकी मक्खन को नरम होने के लिए बाहर रखें।","मध्यम आकार के कटोरे में 3 कप मैदा, नमक, 1 कप Splenda बेकिंग ब्लेंड, बेकिंग सोडा, क्रीम ऑफ टार्टर, 1-1/2 कप Rice Dream, अंडे और 2 छोटे चम्मच वनीला मिलाएँ। पिघला हुआ मक्खन धीरे-धीरे मिलाएँ।","मिश्रण को चिकनाई लगे 9″ x 13″ पैन में डालें।","1 कप नरम किया हुआ मक्खन, Splenda ब्राउन शुगर ब्लेंड, 2 बड़े चम्मच मैदा और दालचीनी को अच्छी तरह मिलने तक मिलाएँ। इसे घोल पर समान रूप से डालें और चाकू से घुमाकर लहरदार डिज़ाइन बनाएँ।","28-32 मिनट बेक करें।","बचे हुए 1 कप Splenda बेकिंग ब्लेंड और पिसी चीनी, 5 बड़े चम्मच राइस मिल्क और 1 छोटा चम्मच वनीला मिलाएँ। केक के गरम रहते हुए उस पर छिड़कें।"],
["यह उच्च कैलोरी वाली मिठाई कैलोरी बढ़ाने के लिए बहुत अच्छी है। इसका आनंद नाश्ते या मिठाई के रूप में लें।","यदि उपलब्ध हो, तो कैलोरी और कार्बोहाइड्रेट घटाने के लिए 1 कप Splenda बेकिंग ब्लेंड और 1 कप पिसी चीनी की जगह 1 कप Ideal® पिसी चीनी का विकल्प इस्तेमाल किया जा सकता है।"],["1 स्टार्च","2 उच्च कैलोरी","2 वसा"]))
R.append(T(3080,"टर्की मीटलोफ़","सारा की किडनी-अनुकूल टर्की मीटलोफ़ रेसिपी में थोड़ा तीखा टर्की सॉसेज शामिल है, जो एक ऐसा तड़का देता है जिसकी आप उम्मीद नहीं करते लेकिन जिसका सचमुच आनंद लेंगे। टर्की मीटलोफ़ जाना-पहचाना लग सकता है, लेकिन यह आपको एक बिल्कुल नए स्वाद से परिचित कराएगा।","6","3 औंस",
["1 पाउंड कीमा टर्की, 7% वसा वाला","3 औंस टर्की सॉसेज","1 पूरा अंडा","1 अंडे की सफेदी","1/2 कप सूखे ब्रेड क्रम्ब्स","1/4 कप ताज़ा अजमोद (पार्सले), कटा हुआ","1 बड़ा चम्मच वूस्टरशायर सॉस","1 छोटा चम्मच Gravy Master® सीज़निंग और ब्राउनिंग सॉस","1 छोटा चम्मच इटैलियन सीज़निंग","1/2 छोटा चम्मच काली मिर्च"],
["ओवन को 350° F पर पहले से गरम करें।","सभी सामग्री को एक बड़े कटोरे में मिलाएँ और अच्छी तरह मिलाएँ।","चिकनाई लगे 9″ x 5″ लोफ पैन में डालें और 1 घंटा बेक करें।","6 बराबर टुकड़ों में काटें और परोसें।"],
["सबसे कम सोडियम वाले ब्रांड का सॉसेज चुनें।","अधिक स्वाद के लिए तीखा और मसालेदार टर्की सॉसेज इस्तेमाल करें।"],["3 मांस","1/2 स्टार्च"]))
R.append(T(3082,"अनार रिफ्रेशर","अनार का रस, नींबू का रस और क्लब सोडा मिलाकर यह उत्सवी, झागदार अनार रिफ्रेशर बनाया जाता है।","1","6 औंस (3/4 कप)",
["1/4 कप अनार का रस","1 बड़ा चम्मच नींबू का रस","1/2 कप क्लब सोडा","1 बड़ा चम्मच अनार के दाने (एरिल्स)","सजावट के लिए नींबू का स्लाइस"],
["अनार का रस और नींबू का रस एक छोटे गिलास में डालें।","ऊपर से क्लब सोडा डालें।","अनार के दाने डालें और नींबू से सजाएँ।"],
["इस रेसिपी में अनार का रस 1/4 कप तक सीमित है। 1 कप अनार के रस में 500 mg से अधिक पोटैशियम होता है।","यदि पसंद हो तो अनार के रस की जगह क्रैनबेरी का रस इस्तेमाल करें। पोटैशियम घटकर 46 mg हो जाता है।","अधिक मिठास के लिए अपने पसंदीदा स्वीटनर की थोड़ी मात्रा डालें।"],["1 फल, मध्यम पोटैशियम"]))
R.append(T(3083,"डम्पलिंग के साथ भेड़ या मटन का स्ट्यू","यदि आपने इसे कभी नहीं आज़माया है, या इसे अक्सर नहीं परोसते हैं, तो एरिज़ोना की DaVita रीनल आहार विशेषज्ञ मिरियम के पास डम्पलिंग के साथ भेड़ या मटन के स्ट्यू की एक रेसिपी है जो स्वादिष्ट, किडनी-अनुकूल है और एक ऐसा पूरा भोजन है जिसमें सब कुछ एक ही बर्तन में पक जाता है।","7","1-1/4 कप",
["6 कप पानी","1 पाउंड भेड़ के स्ट्यू का मांस","1 कप प्याज़, मोटा कटा हुआ","2 कप ज़ुकिनी","3 औंस हरी मिर्च, डिब्बाबंद","2 कप मैदा","1/2 छोटा चम्मच नमक","2 छोटे चम्मच बेकिंग पाउडर","1 छोटा चम्मच चीनी"],
["पानी नापकर स्ट्यू के बर्तन में डालें।","मांस से चर्बी हटाएँ और निवाले के आकार के टुकड़ों में काटें। मांस और हड्डियों को पानी में डालें। स्टोव पर मध्यम आँच पर रखें।","प्याज़ को मोटा काटें। ज़ुकिनी को लंबाई में आधा काटें और 1/2” के स्लाइस में काट लें।","प्याज़, ज़ुकिनी और हरी मिर्च को स्ट्यू में डालें।","स्ट्यू में एक हल्का उबाल आ जाने पर आँच धीमी कर दें और कम से कम 1 घंटे तक धीमी आँच पर पकने दें।","स्ट्यू के पकते समय एक कटोरे में मैदा, नमक, बेकिंग पाउडर और चीनी मिलाएँ।","सूखी सामग्री में गुनगुना पानी मिलाकर गूँथें ताकि आटे की नरम गेंद बन जाए।","आटे को ढककर 20 से 30 मिनट आराम करने दें।","स्ट्यू को 1 घंटे पकाने के बाद, आटे की लगभग 2-1/2” की गेंद को चपटा गोल आकार दें। (इसका बिल्कुल सही या चपटा होना ज़रूरी नहीं है)।","आटे के पैसे के सिक्के के आकार के टुकड़े तोड़कर स्ट्यू में डालें।","2-1/2” के आटे की गेंद को चपटा गोल आकार देते रहें और पैसे के सिक्के के आकार के टुकड़े तोड़कर स्ट्यू में डालते रहें, जब तक सारा आटा स्ट्यू में न चला जाए।","डम्पलिंग को स्ट्यू में अतिरिक्त 20 मिनट पकाएँ।","परोसें और आनंद लें।"],
["डिब्बाबंद मिर्च की जगह 2-3 हैच मिर्च को भूनकर इस्तेमाल करें।"],["2 मांस","1 सब्ज़ी, मध्यम पोटैशियम","1-1/2 स्टार्च"]))
R.append(T(3084,"शेक एंड बेक चिकन एक्सट्रावैगैंज़ा","धैर्य केवल एक गुण नहीं, एक प्रतिभा है। खाना पकाने की तरह ही, करुणा विकसित करना एक ऐसा कौशल है जिसे निखारा जा सकता है, जैसा कि मिनेसोटा की DaVita रीनल आहार विशेषज्ञ मैरी ने दिखाया है। मैरी ने “मरीज़ों के प्रति धैर्य” के अपने कौशल को निखारा है, साथ ही स्वादिष्ट रेसिपी बनाने की अपनी रचनात्मकता को भी, जैसे उनकी किडनी-अनुकूल शेक एंड बेक चिकन एक्सट्रावैगैंज़ा।","6","चिकन का 1 टुकड़ा (बिना हड्डी के 3 औंस)",
["1-1/2 कप सूखे बारीक ब्रेड क्रम्ब्स","1 कप मैदा","4 बड़े चम्मच सूखा अजमोद (पार्सले)","1 बड़ा चम्मच पेपरिका","2 छोटे चम्मच प्याज़ पाउडर","1-1/2 छोटा चम्मच लहसुन पाउडर","1 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच मार्जोरम","1 बड़ा चम्मच थाइम","3 बड़े चम्मच वनस्पति तेल","2 पाउंड चिकन के टुकड़े, हड्डी सहित"],
["ओवन को 375° F पर पहले से गरम करें।","बेकिंग शीट पर वनस्पति तेल लगाएँ (बटर पेपर या सिल्पैट शीट भी इस्तेमाल कर सकते हैं) और एक तरफ रख दें।","ब्रेड क्रम्ब्स, मैदा, अजमोद, पेपरिका, प्याज़ पाउडर, लहसुन पाउडर, काली मिर्च, मार्जोरम और थाइम को मिलाएँ। समान रूप से मिलाने के लिए चलाएँ।","ब्रेड क्रम्ब्स के मिश्रण में तेल डालें और काँटे से पूरी तरह मिलाएँ।","ठंडी, सूखी जगह पर वायुरोधी डिब्बे में रखें या फ्रीज़र में रखें।","चिकन तैयार करने के लिए: चिकन को पानी से धोएँ और अतिरिक्त तरल झाड़ दें, लेकिन चिकन के टुकड़ों को पानी से नम रहने दें।","1 कप ब्रेड क्रम्ब्स का मिश्रण एक साफ प्लास्टिक फ़ूड स्टोरेज बैग में डालें। बैग में एक बार में 1 से 2 चिकन के टुकड़े डालें और समान रूप से परत चढ़ाने के लिए हिलाएँ।","चिकनाई लगी बेकिंग शीट पर रखें और 40 से 45 मिनट बेक करें। 20 मिनट बाद एक बार पलटें।"],
["इस रेसिपी से 3 बार के भोजन के लिए पर्याप्त कोटिंग मिश्रण बनता है। बचे हुए मिश्रण को सीलबंद डिब्बे या फ्रीज़र बैग में रखें और दोबारा उपयोग के समय तक फ्रीज़ करें।","घर पर सूखे ब्रेड क्रम्ब्स बनाने के लिए एक दिन पुरानी ब्रेड को कुरकुरा होने तक टोस्ट करें, लेकिन जलने न दें। ब्लेंडर या फ़ूड प्रोसेसर में कुचल लें।"],["3 मांस","1 स्टार्च"]))
R.append(T(3085,"भुने हुए ब्रसल्स स्प्राउट्स, गाजर और सेब","पतझड़ की सब्ज़ियों के स्वाद को भूनकर और थोड़ा मेपल सिरप डालकर बढ़ाएँ। भुने हुए ब्रसल्स स्प्राउट्स, गाजर और सेब एक किडनी-अनुकूल रेसिपी है, जो किसी भी रात के खाने के लिए आसान है और खास भोजनों में परोसने के लिए भी काफ़ी खास है।","8","1/2 कप",
["20 मध्यम ब्रसल्स स्प्राउट्स","3 बड़ी गाजर","2 मध्यम सेब","1/4 कप ऑलिव ऑयल","2 बड़े चम्मच मेपल सिरप","1 छोटा चम्मच दालचीनी","1/2 छोटा चम्मच जायफल","1/4 छोटा चम्मच नमक"],
["ओवन को 375° F पर पहले से गरम करें। बेकिंग शीट पर नॉनस्टिक कुकिंग स्प्रे करें।","ब्रसल्स स्प्राउट्स को छाँटें और हर एक को आधा काट लें। गाजर छीलकर 1-इंच के टुकड़ों में काटें। सेब का बीच का हिस्सा निकालकर 1/2-इंच के टुकड़ों में काटें।","ब्रसल्स स्प्राउट्स, गाजर और सेब के टुकड़े एक बड़े कटोरे में रखें।","एक छोटे कटोरे में ऑलिव ऑयल, मेपल सिरप और मसाले मिलाएँ। मिलाने के लिए चलाएँ।","सॉस को बड़े कटोरे में डालें और सब्ज़ियों और सेब पर लगाने के लिए चलाएँ। सामग्री को बेकिंग शीट पर रखें। 1/4 छोटा चम्मच नमक छिड़कें।","30 से 40 मिनट बेक करें, जब तक गाजर काँटे से आसानी से न चुभने लगे और ब्रसल्स स्प्राउट्स गहरे होने न लगें।"],
["चाहें तो गाजर की जगह 2 मध्यम शलगम इस्तेमाल करें।","बचे हुए हिस्से को मिश्रित सलाद के पत्तों में डालकर अगले दिन पेट भरने वाला भुनी सब्ज़ियों का सलाद बनाएँ।"],["1-1/2 सब्ज़ी, मध्यम पोटैशियम","1/2 फल, कम पोटैशियम","1 वसा"]))
R.append(T(3090,"श्रिम्प बुलेट्स","श्रिम्प बुलेट्स समुद्री भोजन प्रेमियों के लिए खुशी की बात है क्योंकि झींगे की जगह आसानी से केकड़ा या क्रॉफ़िश का इस्तेमाल किया जा सकता है। लुइज़ियाना के DaVita मरीज़ केन द्वारा बनाए गए श्रिम्प बुलेट्स एक पुराने केजन पसंदीदा व्यंजन को किडनी-अनुकूल मोड़ देते हैं।","10","3 बुलेट्स",
["2 पाउंड कच्चे झींगे","2 कप प्याज़","1 हरी शिमला मिर्च","1 गुच्छा अजमोद (पार्सले)","4 बड़े अंडे","2 छोटे चम्मच लहसुन पाउडर","2 छोटे चम्मच बिना नमक का केजन सीज़निंग","1/2 कप से 1 कप मैदा","तलने के लिए 1 क्वार्ट तेल"],
["झींगे, प्याज़, शिमला मिर्च और अजमोद को बारीक काटें। अंडे फेंट लें।","मैदे को छोड़कर सभी सामग्री को एक मिक्सिंग बाउल में मिलाएँ।","मिलाने के बाद धीरे-धीरे मैदा डालें। थोड़ा-थोड़ा करके मैदा तब तक डालते रहें जब तक मिश्रण गाढ़ा न हो जाए और चम्मच से चिपकने न लगे।","डीप फ्राई करने के लिए एक बड़ी स्किलेट या डीप-फ्रायर में तेल गरम करें। झींगे के घोल को मध्यम आकार के चम्मच से गरम तेल में डालें और दोनों तरफ भूरा और कुरकुरा होने तक पकाएँ।","तेल से निकालकर पेपर टॉवल पर निथार लें। गरमागरम परोसें।"],
["सुझाए गए केजन मसालों में DaVita.com पर घर का बना बिना नमक का केजन सीज़निंग, Mrs. Dash केजन सीज़निंग ब्लेंड या Benoit’s Best Salt-Free Cajun सीज़निंग शामिल हैं। पोटैशियम क्लोराइड वाले उत्पादों से बचें।","तलने की जगह आप घोल से टिक्कियाँ बना सकते हैं और चिकनाई लगी बेकिंग शीट पर 350° F पर सुनहरा भूरा होने तक बेक कर सकते हैं।","झींगे की जगह केकड़ा या क्रॉफ़िश आज़माएँ। दोनों समान रूप से बेहतरीन हैं!"],["3 मांस","1 स्टार्च","1/2 सब्ज़ी, मध्यम पोटैशियम","1 वसा"]))
R.append(T(3091,"बेरीज़ नेपोलियन","कोलोराडो की रीनल आहार विशेषज्ञ मैरी की एक सरल, स्वादिष्ट मिठाई, बेरीज़ नेपोलियन, के साथ रीनल आहार पर भी अपनी मीठा खाने की इच्छा पूरी करें। अकेले या किसी शानदार भोजन के साथ, यह कम पोटैशियम वाली मिठाई किडनी आहार के लिए एकदम सही है।","6","वॉनटन से भरी एक परत वाली ढेरी",
["12 वॉनटन रैपर","2 बड़े चम्मच दानेदार चीनी","1 कप Reddi-Wip® फैट-फ्री व्हिप्ड टॉपिंग","1/2 कप रास्पबेरी","1/2 कप ब्लूबेरी","1 बड़ा चम्मच पिसी चीनी"],
["ओवन को 400° F पर पहले से गरम करें।","एक ऐसी बेकिंग शीट पर कुकिंग स्प्रे करें जिसमें 12 वॉनटन रैपर आ सकें।","वॉनटन रैपर को फैलाएँ और उन पर कुकिंग स्प्रे करें।","वॉनटन रैपर पर दानेदार चीनी छिड़कें।","वॉनटन को 5 मिनट या सुनहरा भूरा होने तक बेक करें; बेकिंग शीट से निकाल लें।","6 वॉनटन रैपर परोसने की ट्रे पर रखें।","हर रैपर के ऊपर 2 बड़े चम्मच व्हिप्ड टॉपिंग, 1 बड़ा चम्मच रास्पबेरी और 1 बड़ा चम्मच ब्लूबेरी रखें।","बेरीज़ के ऊपर दूसरा वॉनटन रैपर रखें।","ऊपरी हिस्से पर पिसी चीनी छिड़कें। चाहें तो उन्हें व्हिप्ड टॉपिंग की एक डली, फल और पुदीने की एक पत्ती से सजाएँ। तुरंत परोसें।"],
["विविधता के लिए रास्पबेरी और ब्लूबेरी की जगह स्ट्रॉबेरी और ब्लैकबेरी इस्तेमाल करें।","कार्बोहाइड्रेट की मात्रा घटाने के लिए चीनी की जगह Splenda® No Calorie दानेदार स्वीटनर इस्तेमाल करें।","यदि वॉनटन फ्रिज में रखे रहें, तो Reddi-Wip पिघल जाएगा। केवल परोसने के लिए तैयार होने पर ही जोड़ें।"],["1/2 स्टार्च","1/2 उच्च कैलोरी"]))
R.append(T(3092,"पॉपी क्रंच","क्या आप हल्का, कुरकुरा और मीठा झटपट नाश्ता ढूँढ रहे हैं? नॉर्थ कैरोलिना की DaVita रीनल आहार विशेषज्ञ जैकी के पास इसका जवाब है: पॉपी क्रंच। बच्चे पॉपकॉर्न से बनी इस ट्रीट को पसंद करेंगे जिस पर मक्खन जैसी मीठी टॉपिंग छिड़की गई है, लेकिन बड़े भी अपना हिस्सा चाहेंगे। और चूँकि यह किडनी-अनुकूल है, किडनी की समस्या वाले लोग भी बिना","12","1 कप",
["12 कप पॉपकॉर्न, फुलाया हुआ, बिना नमक का","1-1/3 कप चीनी","1/2 कप हल्के रंग का कॉर्न सिरप","1 कप मक्खन","1 छोटा चम्मच वनीला एक्सट्रैक्ट"],
["पॉपकॉर्न को उथले पैन में फैलाएँ।","चीनी, कॉर्न सिरप और मक्खन को 1/2 क्वार्ट के सॉसपैन में मिलाएँ।","मध्यम आँच पर तब तक पकाएँ जब तक ठंडे पानी में डाली गई थोड़ी-सी मात्रा पतले धागों में अलग न हो जाए जो सख़्त हों लेकिन भुरभुरे न हों (कैंडी थर्मामीटर पर 280° F)। आँच से उतार लें।","वनीला डालें।","सिरप को पॉपकॉर्न पर डालें और अच्छी तरह परत चढ़ने तक चलाएँ। चिकनाई लगी बेकिंग शीट पर फैलाएँ। टुकड़ों में तोड़ लें।","ठंडा होने दें। परोसने तक वायुरोधी डिब्बे में रखें।"],
["इसे अलग-अलग सर्विंग में बाँटकर रखें, ताकि सप्ताह के दौरान झटपट नाश्ते या मिठाई के लिए उपलब्ध रहे।"],["1 स्टार्च","1 उच्च कैलोरी"]))
save(5,R)
